Lemma ttrace_ebind : forall {A B} (t : itree (exc A)) (f : A -> itree (exc B)) mo tr,
  ttrace (ebind t f) mo tr <->
  texit t mo tr
  \/ (exists mo', tpath t mo tr Unr mo')
  \/ exists tr1 a mo1 tr2, tpath t mo tr1 (Ok a) mo1 /\ ttrace (f a) mo1 tr2 /\ tr = tr1 ++ tr2.
Proof.
